    ('mlb', 'hard', 'Which two teams played the first night game in World Series history, Game 4 in 1971?', 'Reds and Athletics', 'Dodgers and Yankees', 'Pittsburgh Pirates and Baltimore Orioles', 'Mets and Orioles', 'C', 'Reviewed draft MLB-023. Pittsburgh beat Baltimore 4-3 under the lights at Three Rivers Stadium. Verified against https://www.baseball-reference.com/boxes/PIT/PIT197110130.shtml'),
    ('mlb', 'hard', 'Which Athletics slugger founded the 40-40 club with 42 homers and 40 steals in 1988?', 'Rickey Henderson', 'Mark McGwire', 'Barry Bonds', 'Jose Canseco', 'D', 'Reviewed draft MLB-024. Jose Canseco became MLB''s first 40-homer, 40-steal player. Verified against https://www.baseball-reference.com/players/c/cansejo01.shtml'),
    ('mlb', 'hard', 'Which Red Sox pitcher became the first to strike out 20 batters in a nine-inning MLB game, doing it in 1986?', 'Roger Clemens', 'Pedro Martinez', 'Nolan Ryan', 'Dwight Gooden', 'A', 'Reviewed draft MLB-025. Roger Clemens struck out 20 Seattle Mariners on April 29, 1986. Verified against https://www.baseball-reference.com/boxes/BOS/BOS198604290.shtml')
),
inserted_questions as (
  insert into public.questions (
    id,
    sport_id,
    difficulty,
    question_text,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    status,
    eligible_for_daily,
    eligible_for_sport_quiz,
    authoring_method,
    source_notes,
    reviewed_at
  )
  select
    gen_random_uuid(),
    sport.id,
    seed.difficulty,
    seed.question_text,
    seed.option_a,
    seed.option_b,
    seed.option_c,
    seed.option_d,
    seed.correct_option,
    'ready',
    true,
    true,
    'ai_assisted',
    seed.source_notes,
    timezone('utc', now())
  from question_seed seed
  join public.sports sport
    on sport.slug = seed.sport_slug
  where not exists (
    select 1
    from public.questions existing
    where existing.sport_id = sport.id
      and lower(btrim(existing.question_text)) = lower(btrim(seed.question_text))
  )
  returning id
)
select count(*) from inserted_questions;
